$(document).ready(function() {
	$.tablesorter.addParser({
		id: 'abs',
		is: function(s) { return false; },
		format: function(s){ return Math.abs(s); },
		type: 'numeric'
	});

	$.tablesorter.addParser({
		id: 'customDate',
		is: function() { return false; },
		format: function(s){
			s = s.split("(");
			s = s[0];
			s= s.replace(/\-/g, " ");
			s = s.replace(/:/g," ");
			s = s.replace(/T/g," ");
			s = s.replace(/Z/g," ");
			s = s.split(" ");
			return $.tablesorter.formatFloat(new Date(s[0], s[1]-1, s[2], s[3], s[4]).getTime());
		},
		type: 'numeric'
	});

	// add parser through the tablesorter addParser method 
    $.tablesorter.addParser({
        // set a unique id 
        id: 'links',
        is: function(s)
        {
            // return false so this parser is not auto detected 
            return false;
        },
        format: function(s)
        { 
            return s.replace(new RegExp(/<.*?>/),"");
        },
        // set type, either numeric or text
        type: 'text'
    }); 

	$("#FLR_table").tablesorter({
		headers: {
			4: { sorter: 'customDate'},
			5: { sorter: 'customDate'},
			9: { sorter: 'links'}
		}
	});

